using System.Security.Principal;
using System.Text.Json;
namespace CodexLight.Migration;
public sealed record DataDifference(int Added,int Removed,int Changed,long PreviousBytes,long CurrentBytes,int AddedDirectories,int RemovedDirectories);
public static class ManualReconcile {
 static readonly JsonSerializerOptions Json=new(){PropertyNameCaseInsensitive=true,WriteIndented=true};
 static T Read<T>(string path)=>JsonSerializer.Deserialize<T>(File.ReadAllText(MigrationStorage.Canonical(path)),Json)??throw new IOException("Evidence missing");
 internal static DataDifference Difference(DataSnapshot before,DataSnapshot after){var old=before.Files.ToDictionary(x=>x.Path,StringComparer.OrdinalIgnoreCase);var current=after.Files.ToDictionary(x=>x.Path,StringComparer.OrdinalIgnoreCase);return new(current.Keys.Count(x=>!old.ContainsKey(x)),old.Keys.Count(x=>!current.ContainsKey(x)),current.Values.Count(x=>old.TryGetValue(x.Path,out var prior)&&(prior.Bytes!=x.Bytes||!prior.Sha256.Equals(x.Sha256,StringComparison.OrdinalIgnoreCase))),old.Values.Sum(x=>x.Bytes),current.Values.Sum(x=>x.Bytes),after.Directories.Except(before.Directories,StringComparer.OrdinalIgnoreCase).Count(),before.Directories.Except(after.Directories,StringComparer.OrdinalIgnoreCase).Count());}
 internal static void RequireFailedSource(StageReceipt source){if(source.Phase!="RecoveryRequired")throw new IOException("Manual reconciliation requires preserved failed-stage evidence, not a completed/unknown phase");}
 public static void ValidateChain(StageReceipt receipt){if(string.IsNullOrEmpty(receipt.SourceFailedReceipt)){if(new[]{receipt.HandoffPlan,receipt.HandoffPlanSha256,receipt.PreHandoffSnapshot,receipt.PreHandoffSnapshotSha256,receipt.SourceFailedReceiptSha256,receipt.ReconciledSnapshot,receipt.ReconciledSnapshotSha256,receipt.ReconciledHealthPath,receipt.ReconciledHealthSha256}.Any(x=>!string.IsNullOrEmpty(x)))throw new IOException("Partial reconciliation chain refused");return;}var sourcePath=MigrationStorage.Canonical(receipt.SourceFailedReceipt);if(Path.GetDirectoryName(sourcePath)!=receipt.Recovery||MigrationCoordinator.Hash(sourcePath)!=receipt.SourceFailedReceiptSha256)throw new IOException("Failed stage evidence changed");var old=Read<StageReceipt>(sourcePath);RequireFailedSource(old);if(old.Legacy!=receipt.Legacy||old.NewRoot!=receipt.NewRoot||old.Recovery!=receipt.Recovery)throw new IOException("Manual evidence chain identity mismatch");if(string.IsNullOrEmpty(receipt.HandoffPlan)){if(old.ManifestSha256!=receipt.ManifestSha256||old.SetupSha256!=receipt.SetupSha256||old.Target!=receipt.Target||!string.IsNullOrEmpty(receipt.HandoffPlanSha256))throw new IOException("Package changed without prepared handoff plan");}else{var planPath=MigrationStorage.Canonical(receipt.HandoffPlan);if(Path.GetDirectoryName(planPath)!=receipt.Recovery||MigrationCoordinator.Hash(planPath)!=receipt.HandoffPlanSha256)throw new IOException("Prepared handoff plan changed");var plan=Read<StageReceipt>(planPath);ManualPlan.Verify(plan);if(plan.ManifestSha256!=receipt.ManifestSha256||plan.SetupSha256!=receipt.SetupSha256||plan.Target!=receipt.Target||plan.SourceFailedReceipt!=receipt.SourceFailedReceipt||plan.SourceFailedReceiptSha256!=receipt.SourceFailedReceiptSha256||plan.PreHandoffSnapshot!=receipt.PreHandoffSnapshot||plan.PreHandoffSnapshotSha256!=receipt.PreHandoffSnapshotSha256)throw new IOException("Reconciliation differs from authorized plan");}var snapshotPath=MigrationStorage.Canonical(receipt.ReconciledSnapshot);if(Path.GetDirectoryName(snapshotPath)!=receipt.Recovery||!Path.GetFileName(snapshotPath).StartsWith("manual-data-",StringComparison.Ordinal))throw new IOException("Reconciled snapshot scope invalid");if(MigrationCoordinator.Hash(snapshotPath+".manifest.json")!=receipt.ReconciledSnapshotSha256)throw new IOException("Reconciled data manifest changed");var data=Read<DataSnapshot>(snapshotPath+".manifest.json");MigrationStorage.VerifySnapshot(data,snapshotPath);var healthPath=MigrationStorage.Canonical(receipt.ReconciledHealthPath);if(Path.GetDirectoryName(healthPath)!=receipt.Recovery||MigrationCoordinator.Hash(healthPath)!=receipt.ReconciledHealthSha256)throw new IOException("Reconciled health evidence changed");}
 public static void Run(string failedReceipt,string manifestPath,string manifestHash,string setupHash,bool userReportedComplete,bool tasksCompleted,string trustedPlanSha256=""){
  // Inspection is separate from evidence recording. Never invokes Setup or msiexec.
  SafeStage.Execute(manifestPath,manifestHash,setupHash,false,true,false);
  failedReceipt=MigrationStorage.Canonical(failedReceipt);var failedHash=MigrationCoordinator.Hash(failedReceipt);var source=Read<StageReceipt>(failedReceipt);bool planned=source.Phase=="ManualHandoffPlanned";if(planned){source=ManualPlan.LoadBoundPlan(failedReceipt,trustedPlanSha256);ManualPlan.Verify(source);}else{if(!string.IsNullOrEmpty(trustedPlanSha256))throw new IOException("Expected prepared plan, received failed receipt");RequireFailedSource(source);}
  // Reuse strict path/identity checks without modifying or reclassifying original evidence.
  SafeRetire.ValidateReceipt(source with{Phase="StagedOldPreserved"},failedReceipt,manifestHash,setupHash);
  var m=Read<StageRelease>(manifestPath);if(m.Version!=source.Target||MsiProbe.ReadCurrentUser()!=source.Legacy)throw new IOException("Manual install target or original MSI changed");
  void VerifyInstalled(){SafeStage.VerifyFiles(Path.Combine(source.NewRoot,"current"),m.PayloadFiles,true);SafeStage.PackageIdentity(Path.Combine(source.NewRoot,"current"),m);SafeStage.Registration(source.NewRoot,m);if(MigrationCoordinator.Hash(Path.Combine(source.NewRoot,"Update.exe"))!=m.RootUpdaterSha256||MigrationCoordinator.Hash(SafeStage.Member(source.NewRoot,m.RootStubPath))!=m.RootStubSha256)throw new IOException("Manual installation root files mismatch");}
  VerifyInstalled();var originalData=Read<DataSnapshot>(Path.Combine(source.Recovery,"data.manifest.json"));var dataRoot=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CodexLight");if(!originalData.SourceRoot.Equals(dataRoot,StringComparison.OrdinalIgnoreCase))throw new IOException("Original backup outside app scope");MigrationStorage.VerifySnapshot(originalData,Path.Combine(source.Recovery,"data"));if(MigrationCoordinator.Hash(Path.Combine(source.Recovery,"legacy.msi"))!=source.Legacy.SourceSha256)throw new IOException("Original rollback MSI changed");
  if(!userReportedComplete){Console.WriteLine("MANUAL INSPECT ONLY: package/registration/old MSI/backups checked. No health process, data snapshot or new receipt created.");return;}if(!tasksCompleted)throw new IOException("Complete tasks and exit normally before recording manual reconciliation");
  var sid=WindowsIdentity.GetCurrent().User?.Value??throw new IOException("SID absent");var options=new NamedWaitHandleOptions{CurrentUserOnly=true,CurrentSessionOnly=true};using var desktop=new Mutex(true,"CodexLight.Desktop."+sid,options,out bool first);if(!first)throw new IOException("Application still owns desktop mutex; never force stopped");
  try{using var locks=MigrationStorage.AcquireInstallRoots(source.Legacy.InstallRoot,source.NewRoot);SafeStage.Idle(source.Legacy.InstallRoot,source.NewRoot);VerifyInstalled();if(MsiProbe.ReadCurrentUser()!=source.Legacy)throw new IOException("Old MSI changed");
   var health=SafeStage.Run(Path.Combine(source.NewRoot,"current","CodexLight.exe"),"--backend-health-check");using(var doc=JsonDocument.Parse(health.Output)){var h=doc.RootElement;if(health.Code!=0||!h.GetProperty("ok").GetBoolean()||h.GetProperty("scope").GetString()!="native-and-isolated-demo-backend"||h.GetProperty("realAccountVerified").GetBoolean()||!h.GetProperty("gracefulShutdown").GetBoolean()||h.GetProperty("backendVersion").GetString()!=m.Version||!Version.TryParse(h.GetProperty("webViewVersion").GetString(),out _)||!Version.TryParse(h.GetProperty("dotnetVersion").GetString(),out var runtime)||runtime.Major!=10)throw new IOException("Manual installed component health not verified");}
   SafeStage.Idle(source.Legacy.InstallRoot,source.NewRoot);var current=MigrationStorage.CaptureApplicationData();var diff=Difference(originalData,current);if(new DriveInfo(Path.GetPathRoot(source.Recovery)!).AvailableFreeSpace<MigrationStorage.RequiredBytes(current,0,0,0))throw new IOException("Insufficient space to protect post-manual data");
   var id=Guid.NewGuid().ToString("N");var snapshot=Path.Combine(source.Recovery,"manual-data-"+id);MigrationStorage.CopySnapshot(current,snapshot);VerifyInstalled();if(MsiProbe.ReadCurrentUser()!=source.Legacy||MigrationCoordinator.Hash(failedReceipt)!=failedHash)throw new IOException("Source evidence changed during reconciliation");MigrationStorage.VerifySnapshot(originalData,Path.Combine(source.Recovery,"data"));
   var healthPath=Path.Combine(source.Recovery,"manual-health-"+id+".json");MigrationStorage.AtomicReceipt(healthPath,new{RecordedUtc=DateTime.UtcNow,ComponentHealth=JsonSerializer.Deserialize<JsonElement>(health.Output),RealAccountVerified=false,DataDifferences=diff,OriginalDataUnchanged=diff.Added==0&&diff.Removed==0&&diff.Changed==0&&diff.AddedDirectories==0&&diff.RemovedDirectories==0});
   var reconciled=source with{Phase="StagedOldPreserved",SourceFailedReceipt=planned?source.SourceFailedReceipt:failedReceipt,SourceFailedReceiptSha256=planned?source.SourceFailedReceiptSha256:failedHash,HandoffPlan=planned?failedReceipt:"",HandoffPlanSha256=planned?failedHash:"",ReconciledSnapshot=snapshot,ReconciledSnapshotSha256=MigrationCoordinator.Hash(snapshot+".manifest.json"),ReconciledHealthPath=healthPath,ReconciledHealthSha256=MigrationCoordinator.Hash(healthPath)};
   ValidateChain(reconciled);var output=Path.Combine(source.Recovery,"manual-reconciled-"+id+".json");MigrationStorage.AtomicReceipt(output,reconciled);Console.WriteLine(JsonSerializer.Serialize(new{Receipt=output,DataDifferences=diff,OldMsiRetained=true,OriginalFailedReceiptPreserved=true,GuiAndRealAccountAcceptancePending=true},Json));
  }finally{desktop.ReleaseMutex();}
 }
}
